CREATE TABLE users (
  id BINARY(16) PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL,
  display_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'USER', created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL
);
CREATE TABLE user_preferences (
  id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL UNIQUE, roles_json JSON NOT NULL, locations_json JSON NOT NULL, work_modes_json JSON NOT NULL,
  experience_min INT NOT NULL, experience_max INT NOT NULL, manual_approval_required BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL,
  CONSTRAINT fk_preferences_user FOREIGN KEY (user_id) REFERENCES users(id), CHECK (experience_min >= 0 AND experience_max >= experience_min)
);
CREATE TABLE companies (id BINARY(16) PRIMARY KEY, name VARCHAR(255) NOT NULL, normalized_name VARCHAR(255) NOT NULL UNIQUE, website_url VARCHAR(2048), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE jobs (
  id BINARY(16) PRIMARY KEY, company_id BINARY(16), source VARCHAR(80) NOT NULL, external_job_id VARCHAR(255) NOT NULL, fingerprint VARCHAR(128), title VARCHAR(500) NOT NULL,
  description_text MEDIUMTEXT, location VARCHAR(255), work_mode VARCHAR(30), experience_min DECIMAL(4,1), experience_max DECIMAL(4,1), salary_min DECIMAL(14,2), salary_max DECIMAL(14,2), salary_currency VARCHAR(3), posted_at TIMESTAMP(6), application_url VARCHAR(2048), source_url VARCHAR(2048), observed_status VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN', last_checked_at TIMESTAMP(6), discovered_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL,
  CONSTRAINT uq_jobs_source_external UNIQUE(source, external_job_id), CONSTRAINT fk_jobs_company FOREIGN KEY (company_id) REFERENCES companies(id), INDEX ix_jobs_fingerprint(fingerprint), INDEX ix_jobs_discovered_at(discovered_at)
);
CREATE TABLE job_skills (id BINARY(16) PRIMARY KEY, job_id BINARY(16) NOT NULL, skill_name VARCHAR(120) NOT NULL, skill_type VARCHAR(30) NOT NULL, CONSTRAINT fk_job_skills_job FOREIGN KEY (job_id) REFERENCES jobs(id), UNIQUE(job_id, skill_name, skill_type));
CREATE TABLE master_resumes (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, version_number INT NOT NULL, tex_path VARCHAR(1024) NOT NULL, pdf_path VARCHAR(1024), content_hash CHAR(64) NOT NULL, parsed_profile JSON, uploaded_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_master_user FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(user_id, version_number), UNIQUE(user_id, content_hash));
CREATE TABLE job_matches (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, job_id BINARY(16) NOT NULL, overall_score DECIMAL(5,2) NOT NULL, required_skills_score DECIMAL(5,2) NOT NULL, experience_score DECIMAL(5,2) NOT NULL, framework_score DECIMAL(5,2) NOT NULL, project_score DECIMAL(5,2) NOT NULL, title_score DECIMAL(5,2) NOT NULL, location_score DECIMAL(5,2) NOT NULL, evidence JSON NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_match_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_match_job FOREIGN KEY(job_id) REFERENCES jobs(id), UNIQUE(user_id, job_id));
CREATE TABLE hr_contacts (id BINARY(16) PRIMARY KEY, company_id BINARY(16) NOT NULL, full_name VARCHAR(255), email VARCHAR(320), designation VARCHAR(255), source_url VARCHAR(2048) NOT NULL, verification_status VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN', verification_method VARCHAR(255), discovered_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_contact_company FOREIGN KEY(company_id) REFERENCES companies(id), INDEX ix_contacts_company(company_id));
CREATE TABLE custom_resumes (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, job_id BINARY(16) NOT NULL, version_number INT NOT NULL, tex_path VARCHAR(1024) NOT NULL, pdf_path VARCHAR(1024), generation_report JSON NOT NULL, quality_status VARCHAR(30) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_custom_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_custom_job FOREIGN KEY(job_id) REFERENCES jobs(id), UNIQUE(job_id, version_number));
CREATE TABLE applications (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, job_id BINARY(16) NOT NULL, custom_resume_id BINARY(16), status VARCHAR(30) NOT NULL, recipient_email VARCHAR(320), email_subject VARCHAR(998), email_body MEDIUMTEXT, email_version INT NOT NULL DEFAULT 0, gmail_message_id VARCHAR(255), idempotency_key VARCHAR(128), sent_at TIMESTAMP(6), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_application_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_application_job FOREIGN KEY(job_id) REFERENCES jobs(id), CONSTRAINT fk_application_resume FOREIGN KEY(custom_resume_id) REFERENCES custom_resumes(id), UNIQUE(user_id, job_id), UNIQUE(idempotency_key));
CREATE TABLE approvals (id BINARY(16) PRIMARY KEY, application_id BINARY(16) NOT NULL, email_version INT NOT NULL, custom_resume_id BINARY(16) NOT NULL, approved_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_approval_application FOREIGN KEY(application_id) REFERENCES applications(id), CONSTRAINT fk_approval_resume FOREIGN KEY(custom_resume_id) REFERENCES custom_resumes(id), UNIQUE(application_id, email_version));
CREATE TABLE email_logs (id BINARY(16) PRIMARY KEY, application_id BINARY(16) NOT NULL, gmail_message_id VARCHAR(255), status VARCHAR(30) NOT NULL, request_fingerprint CHAR(64), error_message TEXT, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_email_application FOREIGN KEY(application_id) REFERENCES applications(id), INDEX ix_email_application(application_id));
CREATE TABLE application_status_history (id BINARY(16) PRIMARY KEY, application_id BINARY(16) NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, changed_at TIMESTAMP(6) NOT NULL, note VARCHAR(1000), CONSTRAINT fk_status_application FOREIGN KEY(application_id) REFERENCES applications(id), INDEX ix_status_application(application_id, changed_at));
CREATE TABLE oauth_connections (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, provider VARCHAR(50) NOT NULL, encrypted_access_token MEDIUMTEXT NOT NULL, encrypted_refresh_token MEDIUMTEXT, expires_at TIMESTAMP(6), scopes VARCHAR(2000), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_oauth_user FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(user_id, provider));
CREATE TABLE sync_logs (id BINARY(16) PRIMARY KEY, user_id BINARY(16), integration VARCHAR(50) NOT NULL, status VARCHAR(30) NOT NULL, details JSON, attempted_at TIMESTAMP(6) NOT NULL, completed_at TIMESTAMP(6), CONSTRAINT fk_sync_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE background_tasks (id BINARY(16) PRIMARY KEY, user_id BINARY(16), task_type VARCHAR(50) NOT NULL, status VARCHAR(30) NOT NULL, payload JSON NOT NULL, attempts INT NOT NULL DEFAULT 0, max_attempts INT NOT NULL DEFAULT 3, next_attempt_at TIMESTAMP(6), error_message TEXT, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_task_user FOREIGN KEY(user_id) REFERENCES users(id), INDEX ix_task_schedule(status, next_attempt_at));
